package br.com.conectatea.vinculo.api;
import br.com.conectatea.auditoria.application.AuditLogService; import br.com.conectatea.security.AuthenticatedUser; import br.com.conectatea.shared.domain.BusinessRuleException; import br.com.conectatea.usuario.infrastructure.UsuarioRepository; import br.com.conectatea.vinculo.domain.*; import br.com.conectatea.vinculo.infrastructure.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.Instant; import java.util.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.core.Authentication; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/administracao/pedidos-primeiro-gestor") @io.swagger.v3.oas.annotations.tags.Tag(name="Administração")
public class AdministracaoGestorController {
 private final PedidoPrimeiroGestorRepository pedidos; private final UsuarioRepository usuarios; private final VinculoResponsavelRepository vinculos; private final HistoricoVinculoRepository historico; private final AuditLogService auditoria; private final br.com.conectatea.crianca.infrastructure.CriancaRepository criancas;
 public AdministracaoGestorController(PedidoPrimeiroGestorRepository p,UsuarioRepository u,VinculoResponsavelRepository v,HistoricoVinculoRepository h,AuditLogService a,br.com.conectatea.crianca.infrastructure.CriancaRepository c){pedidos=p;usuarios=u;vinculos=v;historico=h;auditoria=a;criancas=c;}
 @GetMapping @Transactional(readOnly=true) public List<Response> listar(Authentication auth,@RequestParam(defaultValue="PENDENTE") String status){admin(auth);return pedidos.findAllByStatusOrderByCriadoEmAscIdAsc(status).stream().map(Response::from).toList();}
 @PatchMapping("/{id}") @Transactional public Response decidir(Authentication auth,@PathVariable Long id,@Valid @RequestBody Decision req){var operador=admin(auth);var pedido=pedidos.findByIdForUpdate(id).orElseThrow();if(!"PENDENTE".equals(pedido.getStatus()))throw new BusinessRuleException("REQUEST_ALREADY_DECIDED","Pedido já decidido");var existentes=vinculos.lockActiveByChild(pedido.getCriancaId(),StatusVinculo.VINCULADO);boolean temGestor=existentes.stream().anyMatch(br.com.conectatea.vinculo.domain.VinculoResponsavelCrianca::isGestor);if(req.aprovar()&&temGestor)throw new BusinessRuleException("MANAGER_ALREADY_EXISTS","Bootstrap não se aplica a criança que já possui gestor");if(req.aprovar()){var sol=usuarios.findById(pedido.getSolicitanteUsuarioId()).orElseThrow();if(!sol.isAtivo()||!sol.isEmailConfirmado())throw new BusinessRuleException("APPLICANT_NOT_ELIGIBLE","Solicitante não elegível");var crianca=criancas.findById(pedido.getCriancaId()).orElseThrow();if(crianca.isArquivada())throw new BusinessRuleException("CHILD_ARCHIVED","Criança arquivada");}pedido.decidir(req.aprovar(),operador.getId(),req.referenciaVerificacao(),req.motivo(),Instant.now());if(req.aprovar()){var link=vinculos.findByResponsavelIdAndCriancaId(pedido.getSolicitanteUsuarioId(),pedido.getCriancaId()).orElseGet(()->vinculos.save(new VinculoResponsavelCrianca(pedido.getSolicitanteUsuarioId(),pedido.getCriancaId())));link.vincularComo(PapelCirculo.RESPONSAVEL_GESTOR);historico.save(new HistoricoVinculo(pedido.getCriancaId(),operador.getId(),pedido.getSolicitanteUsuarioId(),null,"PRIMEIRO_GESTOR_APROVADO","RESPONSAVEL_GESTOR","referencia="+req.referenciaVerificacao()));}auditoria.record(operador.getId(),req.aprovar()?"PRIMEIRO_GESTOR_APROVADO":"PRIMEIRO_GESTOR_RECUSADO","PEDIDO_PRIMEIRO_GESTOR",pedido.getId(),pedido.getCriancaId(),null,"SUCESSO","referencia="+req.referenciaVerificacao());return Response.from(pedido);}
 @GetMapping("/{id}") @Transactional(readOnly=true) public Response obter(Authentication auth,@PathVariable Long id){admin(auth);return Response.from(pedidos.findById(id).orElseThrow());}
 private br.com.conectatea.usuario.domain.Usuario admin(Authentication auth){var principal=(AuthenticatedUser)auth.getPrincipal();return usuarios.findById(principal.id()).filter(u->u.isAtivo()&&u.isAdministrador()).orElseThrow(()->new AccessDeniedException("Capacidade administrativa específica necessária"));}
 public record Decision(boolean aprovar,@NotBlank @Size(max=300) String referenciaVerificacao,@NotBlank @Size(max=500) String motivo){}
 public record Response(Long id,Long criancaId,Long solicitanteUsuarioId,String vinculoDeclarado,String status,Instant criadoEm,Long operadorUsuarioId,String referenciaVerificacao,String motivo,Instant decididoEm){static Response from(PedidoPrimeiroGestor p){return new Response(p.getId(),p.getCriancaId(),p.getSolicitanteUsuarioId(),p.getVinculoDeclarado(),p.getStatus(),p.getCriadoEm(),p.getOperadorUsuarioId(),p.getReferenciaVerificacao(),p.getMotivoDecisao(),p.getDecididoEm());}}
}
